Definition V4K1 : list reg := [3; 4; 20; 27]%bv.

Definition V4SAVED : list reg := [26; 25; 24; 23; 22; 21; 20; 19; 18; 9; 8; 1]%bv.

Definition v4_B1 (E : Z) : Prop :=
  forall (R F : bvmap 5 word) (fc : bv 32) (m : mem) (v b cap src spz lo : Z),
    getr R 10 = wz v -> getr R 11 = wz src -> getr R 2 = wz spz ->
    ACONST m -> fldA m v 8 b -> fldA m (v + 8) 8 (b + 4 * cap) -> fldA m (v + 16) 8 (b + 4 * cap) -> gz m v 24 ->
    stk asegs m lo spz -> lo <= spz - 96 -> 2 ^ 45 <= spz - 96 -> spz <= 2 ^ 47 ->
    0x6e6000 <= v -> v + 24 <= 2 ^ 47 -> (v + 24 <= spz - 96 \/ spz <= v) ->
    0 <= b -> b + 4 * cap < 2 ^ 47 -> 0 <= cap <= 2 ^ 24 ->
    exists R' M1,
      CatSim.msteps asegs (MS R F (wz E) fc None m (seg_rom asegs)) (MS R' F (wz AOPNEW) fc None M1 (seg_rom asegs))
      /\ munch [(spz - 96, spz)] m M1 /\ wmono asegs m M1
      /\ rw_cells asegs M1 (spz - 96) (map (fun r => C8 (getr R r)) V4SAVED)
      /\ getr R' 1 = wz (E + 0xcc) /\ getr R' 2 = wz (spz - 96) /\ getr R' 10 = wz (4 * vgrow cap)
      /\ getr R' 8 = wz (v + 8) /\ getr R' 9 = wz v /\ getr R' 18 = wz (v + 16) /\ getr R' 19 = wz (4 * vgrow cap)
      /\ getr R' 21 = wz src /\ getr R' 22 = wz (4 * cap) /\ getr R' 23 = wz (sh v) /\ getr R' 24 = wz (sh (v + 8))
      /\ getr R' 25 = wz (sh (v + 16)) /\ getr R' 26 = wz ASHADOW_BASE
      /\ (forall r, In r V4K1 -> getr R' r = getr R r).

Definition V4K3 : list reg := [2; 3; 4; 8; 9; 18; 19; 21; 23; 24; 25; 26; 27]%bv.
Definition V4K3B : list reg := [2; 3; 4; 8; 9; 18; 19; 21; 24; 25; 26; 27]%bv.
Definition v4_B3pre (R : bvmap 5 word) (m : mem) (v b cap b' src x k spz : Z) : Prop :=
  getr R 10 = wz b' /\ getr R 2 = wz (spz - 96) /\ getr R 8 = wz (v + 8) /\ getr R 9 = wz v /\ getr R 18 = wz (v + 16)
  /\ getr R 21 = wz src /\ getr R 22 = wz (4 * cap) /\ getr R 23 = wz (sh v) /\ getr R 24 = wz (sh (v + 8))
  /\ getr R 25 = wz (sh (v + 16)) /\ getr R 26 = wz ASHADOW_BASE
  /\ fldA m v 8 b /\ fldA m (v + 8) 8 (b + 4 * cap) /\ fldA m (v + 16) 8 (b + 4 * cap) /\ gz m v 24
  /\ fldA m src 4 x /\ shk m src k /\ (k = 0 \/ src mod 8 + 4 <= k < 8) /\ 0 <= x < 2 ^ 32 /\ src mod 4 = 0 /\ 0 <= src /\ src + 4 <= 2 ^ 47
  /\ wr_at asegs m (b' + 4 * cap) 4 /\ b' mod 16 = 0
  /\ (b' + 4 * cap + 4 <= 0x7fff8000 \/ 0x10007fff8000 <= b') /\ (v + 24 <= b' + 4 * cap \/ b' + 4 * cap + 4 <= v)
  /\ 2 ^ 45 <= spz - 96 /\ spz <= 2 ^ 47 /\ 0x6e6000 <= v /\ v + 24 <= 2 ^ 47 /\ 0x6e6000 <= b' /\ b' + 4 * cap + 4 <= 2 ^ 47
  /\ 0 <= b /\ b + 4 * cap < 2 ^ 47 /\ 0 <= cap <= 2 ^ 24.

Definition v4_B3a (E : Z) : Prop :=
  forall (R F : bvmap 5 word) (fc : bv 32) (m : mem) (v b cap b' src x k spz : Z),
