Ltac v4_finA E R HR KL :=
  match goal with HR' : regs_ok E _ ?R', Hlf : log_flat E _, Hms : CatSim.msteps _ _ _ |- _ =>
    lazymatch R' with R => fail | _ => v4_fin E R HR HR' Hlf Hms KL end end.
Ltac v4_frameA E := match goal with Hlf : log_flat E _ |- _ => v4_frame E Hlf end.

Definition v4_at (ss : sym_state) (pc ra : Z) : sym_state := SS pc (sr_upd (s_regs ss) 1 (ELit ra)) (s_log ss) (s_know ss) (s_next ss).
Definition v4_pcat (ss : sym_state) (pc : Z) : sym_state := SS pc (s_regs ss) (s_log ss) (s_know ss) (s_next ss).

Definition v4_x1 (d : bool) := sym_exec asegs 200 true [AOPNEW] (SCR [d] [] []) (SS 0xf7b88 v4_sr1 [] v4_kn1F 40) [].
Definition v4_ss1T : sym_state := Eval vm_compute in fst (fst (v4_x1 true)).
Definition v4_ss1F : sym_state := Eval vm_compute in fst (fst (v4_x1 false)).
Definition v4_scs1T : list sidecond := Eval vm_compute in snd (fst (v4_x1 true)).
Definition v4_scs1F : list sidecond := Eval vm_compute in snd (fst (v4_x1 false)).
Definition v4_run1 (E ra : Z) : Prop :=
  sym_exec asegs 200 true [AOPNEW] (SCR [true] [] []) (SS E v4_sr1 [] v4_kn1F 40) [] = (v4_at v4_ss1T AOPNEW ra, v4_scs1T, SCR [] [] [])
  /\ sym_exec asegs 200 true [AOPNEW] (SCR [false] [] []) (SS E v4_sr1 [] v4_kn1F 40) [] = (v4_at v4_ss1F AOPNEW ra, v4_scs1F, SCR [] [] []).

Ltac v4_run FX EQ HR HK HS ss0 :=
  let R' := fresh "R'" in let HR' := fresh "HR'" in let Hlf := fresh "Hlf" in let Hms := fresh "Hms" in
  destruct (@SymRun3.run_sound FX asegs _ _ _ _ _ _ _ _ _ _ _ _ (seg_rom asegs) _ EQ HR HK HS) as (R' & HR' & Hlf & Hms);
  unfold v4_at, v4_pcat in HR', Hlf, Hms; unfold ss0 in HR', Hlf, Hms; cbn [s_regs s_log s_pc] in HR', Hlf, Hms.

