ltac2:(KReplay.run1 (kr_t_LbA_ContV4R ()) [] "h01Wh11ah21Hh32a'h41mh51np;1p;4p;3p;7g0013j10Tg001Xj13Tg0026j12Tg002Yj14Tg0226j41Tg00@;j36Tg00`oj75Tg00;H#0#0#0R0#0#0#0#3#2%30#2#4[g00;mR0g00=HR1f3R2f2R3f0R4C1A6023P0P2P1f6P4P2C1P1f7f5R5f4R6C1]0X10P1P5P2P3C1P4W0P6P4f1F5W2W0X50X30W1W4o"). Qed.

Ltac v4_cell1 E Hlf :=
  lazymatch goal with |- rw_cells _ (mem_denot _ ?m0 ?lg) ?A [?c] =>
    change lg with ([] ++ lg);
    lazymatch goal with |- rw_cells _ (mem_denot _ _ ([] ++ [SE ?a ?w ?v])) _ _ =>
      eapply (rw_cells_mem_denot_w E m0 [] a w v [] A c);
      [ exact Hlf | apply Forall_nil | unfold estart; cbn [a_base a_off]; evs; unfold wz; repeat (first [rewrite w_add by lia | rewrite w_mul by lia]); rewrite u64_of_Z by lia; lia
      | first [ eassumption | match goal with W : wr_at _ _ ?a _ |- wr_at _ _ ?a' _ => eapply (wr_at_eqA _ a); [exact W | lia] end ]
      | reflexivity | exact I | evs; rewrite le4_ext by lia; reflexivity ]
    end
  end.
Lemma munch_eq1 : forall (m m' : mem) a b a' b', munch [(a, b)] m m' -> a = a' -> b = b' -> munch [(a', b')] m m'.
