                | rewrite w_sra4 by lia | rewrite w_sra1 by lia ]);
  rewrite ?u64_of_Z by lia.
Ltac v4_munch1 E Hlf base w :=
  lazymatch goal with |- munch _ ?m0 (mem_denot _ _ _) =>
    let MU := fresh "MU" in
    pose proof (munch_mem_denot_sb [(0, w)] base E m0 _ Hlf ltac:(vm_cast_no_check (@eq_refl bool true))) as MU;
    cbn [map fst snd] in MU;
    eapply munch_eq1; [exact MU | evs; wnorm; lia | evs; wnorm; lia] end.

