Lemma v4_kn3a_ok : forall R m v b cap b' src x k spz, v4_B3pre R m v b cap b' src x k spz -> 16 <= b -> 1 <= cap -> sh0 m (b' + 4 * cap) ->
  (k = 0 -> know_ok asegs (v4_E3 R v b cap b' src x k spz) m v4_kn3a0F /\ scs_denot asegs m (v4_E3 R v b cap b' src x k spz) v4_scs3a0)
