Definition V4K5 : list reg := [2; 3; 4; 8; 9; 18; 19; 20; 21; 24; 25; 26; 27]%bv.
Definition v4_B5 (E : Z) : Prop :=
  forall (R F : bvmap 5 word) (fc : bv 32) (m : mem) (v b cap b' spz : Z),
    getr R 2 = wz (spz - 96) -> getr R 8 = wz (v + 8) -> getr R 9 = wz v -> getr R 18 = wz (v + 16) -> getr R 20 = wz b'
    -> getr R 22 = wz (b' + 4 * cap) -> getr R 23 = wz (sh v) -> getr R 24 = wz (sh (v + 8)) -> getr R 25 = wz (sh (v + 16))
    -> getr R 26 = wz ASHADOW_BASE ->
    fldA m v 8 b -> fldA m (v + 8) 8 (b + 4 * cap) -> fldA m (v + 16) 8 (b + 4 * cap) -> gz m v 24 ->
    2 ^ 45 <= spz - 96 -> spz <= 2 ^ 47 -> 0x6e6000 <= v -> v + 24 <= 2 ^ 47 -> 0x6e6000 <= b' -> b' + 4 * cap + 4 <= 2 ^ 47 ->
    16 <= b -> b + 4 * cap < 2 ^ 47 -> 1 <= cap <= 2 ^ 24 ->
    exists R' M5,
      CatSim.msteps asegs (MS R F (wz (E + 0x12c)) fc None m (seg_rom asegs)) (MS R' F (wz AASAN_MEMCPY) fc None M5 (seg_rom asegs))
      /\ M5 = m
      /\ getr R' 1 = wz (E + 0x158) /\ getr R' 10 = wz b' /\ getr R' 11 = wz b /\ getr R' 12 = wz (4 * cap)
      /\ getr R' 22 = wz b' /\ getr R' 23 = wz (b' + 4 * cap + 4)
      /\ (forall r, In r V4K5 -> getr R' r = getr R r).

