Definition V4K7 : list reg := [2; 3; 4; 8; 18; 19; 20; 22; 23; 24; 25; 26; 27]%bv.
Definition v4_B7 (E : Z) : Prop :=
  forall (R F : bvmap 5 word) (fc : bv 32) (m : mem) (v b cap cap' b' spz : Z),
    getr R 2 = wz (spz - 96) -> getr R 8 = wz (v + 8) -> getr R 9 = wz v -> getr R 18 = wz (v + 16) -> getr R 19 = wz (4 * cap')
    -> getr R 20 = wz b' -> getr R 22 = wz b' -> getr R 23 = wz (b' + 4 * cap + 4) -> getr R 24 = wz (sh (v + 8))
    -> getr R 25 = wz (sh (v + 16)) -> getr R 26 = wz ASHADOW_BASE ->
    fldA m v 8 b -> fldA m (v + 16) 8 (b + 4 * cap) -> gz m v 24 -> wr_at asegs m v 24 ->
    2 ^ 45 <= spz - 96 -> spz <= 2 ^ 47 -> 0x6e6000 <= v -> v + 24 <= 2 ^ 47 -> (v + 24 <= 0x7fff8000 \/ 0x10007fff8000 <= v) ->
    0x6e6000 <= b' -> b' + 4 * cap' <= 2 ^ 47 ->
    0 <= b -> b + 4 * cap < 2 ^ 47 -> 0 <= cap <= 2 ^ 24 -> cap + 1 <= cap' <= 2 ^ 25 ->
    exists R' M7,
      CatSim.msteps asegs (MS R F (wz (E + 0x158)) fc None m (seg_rom asegs)) (MS R' F (wz AANNOTATE_CC) fc None M7 (seg_rom asegs))
      /\ munch [(v, v + 24)] m M7 /\ wmono asegs m M7
      /\ rw_cells asegs M7 v [C8 (wz b'); C8 (wz (b' + 4 * cap + 4)); C8 (wz (b' + 4 * cap'))]
      /\ getr R' 1 = wz (E + 0x188) /\ getr R' 9 = wz (b + 4 * cap) /\ getr R' 10 = wz b' /\ getr R' 11 = wz (b' + 4 * cap')
      /\ getr R' 12 = wz (b' + 4 * cap') /\ getr R' 13 = wz (b' + 4 * cap + 4) /\ getr R' 21 = wz b
      /\ (forall r, In r V4K7 -> getr R' r = getr R r).

Definition v4_E7 (R : bvmap 5 word) (v b cap cap' b' spz : Z) : env := Eseed R [wz b'; wz (spz - 96); wz 0; wz v; wz (4 * cap'); wz 0; wz cap; wz b].
Definition v4_sr7 : list expr :=
