Definition V4K11 : list reg := [3; 4; 5; 6; 7; 11; 12; 13; 14; 15; 16; 17; 27; 28; 29; 30; 31]%bv.
Definition v4_B11 (E : Z) : Prop :=
  forall (R F : bvmap 5 word) (fc : bv 32) (m : mem) (spz : Z) (x26 x25 x24 x23 x22 x21 x20 x19 x18 x9 x8 x1 : word),
    getr R 2 = wz (spz - 96) ->
    rw_cells asegs m (spz - 96) (map (fun w => C8 w) [x26; x25; x24; x23; x22; x21; x20; x19; x18; x9; x8; x1]) ->
    2 ^ 45 <= spz - 96 -> spz <= 2 ^ 47 ->
    exists R',
      CatSim.msteps asegs (MS R F (wz (E + 0x1a4)) fc None m (seg_rom asegs)) (MS R' F (wz (E + 0x1dc)) fc None m (seg_rom asegs))
      /\ getr R' 1 = x1 /\ getr R' 2 = wz spz /\ getr R' 8 = x8 /\ getr R' 9 = x9 /\ getr R' 10 = getr R 8
      /\ getr R' 18 = x18 /\ getr R' 19 = x19 /\ getr R' 20 = x20 /\ getr R' 21 = x21 /\ getr R' 22 = x22 /\ getr R' 23 = x23
      /\ getr R' 24 = x24 /\ getr R' 25 = x25 /\ getr R' 26 = x26
      /\ (forall r, In r V4K11 -> getr R' r = getr R r).

Definition v4_sr11 : list expr := srs sr_id [(2%bv, EVar 32)].
Definition v4_kn11 : list kentry :=
  [ KWord (SA (EVar 32) 0) 8 (EVar 33); KWord (SA (EVar 32) 8) 8 (EVar 34); KWord (SA (EVar 32) 16) 8 (EVar 35);
    KWord (SA (EVar 32) 24) 8 (EVar 36); KWord (SA (EVar 32) 32) 8 (EVar 37); KWord (SA (EVar 32) 40) 8 (EVar 38);
    KWord (SA (EVar 32) 48) 8 (EVar 39); KWord (SA (EVar 32) 56) 8 (EVar 40); KWord (SA (EVar 32) 64) 8 (EVar 41);
    KWord (SA (EVar 32) 72) 8 (EVar 42); KWord (SA (EVar 32) 80) 8 (EVar 43); KWord (SA (EVar 32) 88) 8 (EVar 44);
    KRange (EVar 32) (2 ^ 45) (2 ^ 47) ].
Definition v4_x11 := sym_exec asegs 200 true [] (SCR [] [] []) (SS 0xf7d2c v4_sr11 [] v4_kn11 50) [].
Definition v4_ss11 : sym_state := Eval vm_compute in fst (fst v4_x11).
Definition v4_scs11 : list sidecond := Eval vm_compute in snd (fst v4_x11).
Definition v4_run11 (pc pce : Z) : Prop :=
  sym_exec asegs 200 true [] (SCR [] [] []) (SS pc v4_sr11 [] v4_kn11 50) [] = (v4_pcat v4_ss11 pce, v4_scs11, SCR [] [] []).

